"""Summarize workflow tables without changing the node."""
import argparse
from datetime import datetime, timedelta, timezone
import json
from pathlib import Path
import re


REQUIRED = {
    "routines": {"name", "every", "last_time", "last_code"},
    "schedule": {"name", "at", "claimed"},
}
PERIODS = {"s": 1, "m": 60, "h": 3600, "d": 86400}


def reject_constant(value):
    raise ValueError(value)


def read_table(node, table, bad):
    try:
        with (node / "wf" / (table + ".json")).open(encoding="utf-8") as stream:
            data = json.load(stream, parse_constant=reject_constant)
    except FileNotFoundError:
        return []
    except (OSError, UnicodeError, ValueError):
        bad.append({"table": table, "row": None, "why": "bad_table"})
        return []
    if not (isinstance(data, dict)
            and data.get("contract") == "wf-table/1"
            and isinstance(data.get("columns"), list)
            and all(isinstance(col, str) for col in data["columns"])
            and isinstance(data.get("rows"), list)):
        bad.append({"table": table, "row": None, "why": "bad_table"})
        return []
    return data["rows"]


def timestamp(value, now):
    stamp = datetime.fromisoformat(value)
    return stamp if stamp.tzinfo is not None else stamp.replace(tzinfo=now.tzinfo)


def utc_seconds(stamp):
    return stamp.astimezone(timezone.utc).replace(microsecond=0).isoformat().replace("+00:00", "Z")


def routine(row, now):
    if re.fullmatch(r"[1-9][0-9]*[rsmhd]", row["every"]) is None:
        raise ValueError("invalid period")
    stamp = timestamp(row["last_time"], now) if row["last_time"] else None
    raw_code = row["last_code"]
    if raw_code == "":
        code = None
    elif raw_code == "running":
        code = "running"
    elif re.fullmatch(r"[+-]?[0-9]+", raw_code):
        code = int(raw_code)
    else:
        raise ValueError("invalid code")
    next_stamp = None
    if stamp is not None and row["every"][-1] != "r":
        seconds = int(row["every"][:-1]) * PERIODS[row["every"][-1]]
        next_stamp = stamp + timedelta(seconds=seconds)
    if code == "running":
        state = "running"
    elif stamp is None:
        state = "never"
    elif isinstance(code, int) and code != 0:
        state = "failed"
    elif next_stamp is not None and now >= next_stamp:
        state = "overdue"
    else:
        state = "ok"
    return {"name": row["name"], "every": row["every"],
            "last_time": row["last_time"] if stamp is not None else None,
            "last_code": code, "state": state,
            "next": utc_seconds(next_stamp) if next_stamp is not None else None}


def scheduled(row, now):
    at = timestamp(row["at"], now)
    state = "interrupted" if row["claimed"] else "due" if at <= now else "pending"
    return {"name": row["name"], "at": row["at"], "state": state}


def summarize(node, now):
    bad = []
    result = {"v": 1, "routines": [], "schedule": [],
              "counts": {"routines": dict.fromkeys(
                  ("running", "never", "failed", "overdue", "ok"), 0),
                         "schedule": dict.fromkeys(("interrupted", "due", "pending"), 0)},
              "bad": bad}
    for table in ("routines", "schedule"):
        seen = set()
        for index, row in enumerate(read_table(node, table, bad)):
            name = row.get("name") if isinstance(row, dict) else None
            if isinstance(name, str) and name:
                if name in seen:
                    bad.append({"table": table, "row": index, "why": "dup_name"})
                    continue
                seen.add(name)
            if (not isinstance(row, dict) or not REQUIRED[table].issubset(row)
                    or not isinstance(name, str) or not name
                    or not all(isinstance(value, str) for value in row.values())):
                bad.append({"table": table, "row": index, "why": "bad_row"})
                continue
            try:
                item = routine(row, now) if table == "routines" else scheduled(row, now)
            except (ValueError, OverflowError):
                bad.append({"table": table, "row": index, "why": "bad_row"})
                continue
            result[table].append(item)
            result["counts"][table][item["state"]] += 1
        result[table].sort(key=lambda item: item["name"])
    bad.sort(key=lambda item: (item["table"], -1 if item["row"] is None else item["row"], item["why"]))
    return result


def main(argv=None):
    parser = argparse.ArgumentParser(description="Read-only workflow table summary")
    parser.add_argument("folder", type=Path)
    parser.add_argument("--now", required=True)
    args = parser.parse_args(argv)
    if not args.folder.is_dir():
        parser.error("folder must be a directory")
    try:
        now = datetime.fromisoformat(args.now)
    except ValueError:
        parser.error("--now must be an ISO datetime with a timezone")
    if now.tzinfo is None:
        parser.error("--now must include a timezone")
    print(json.dumps(summarize(args.folder, now), ensure_ascii=True, separators=(",", ":")))
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
